WITH deduped AS (SELECT id, event_type, event_time, duration_sec FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec DESC NULLS LAST, id ASC) AS row_num FROM web_events) x WHERE row_num = 1) SELECT id, event_type, event_time, duration_sec, CASE WHEN event_type RLIKE '^(page_view|click)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS event_type_zone FROM deduped ORDER BY duration_sec DESC NULLS LAST
